def determine_winner(n, sequence):
    def nim_sum(state):
        xor_sum = 0
        min_value = min(state)
        for value in state:
            xor_sum ^= value
        return xor_sum, min_value

    def can_win(state, is_bitlgm_turn):
        xor_sum, min_value = nim_sum(state)
        if xor_sum == 0:
            return not is_bitlgm_turn

        for i in range(n):
            for x in range(1, state[i] + 1):
                new_state = list(state)
                new_state[i] -= x
                if not can_win(new_state, not is_bitlgm_turn):
                    return True

        for x in range(1, min_value + 1):
            new_state = [value - x for value in state]
            if not can_win(new_state, not is_bitlgm_turn):
                return True

        return False

    if can_win(sequence, True):
        return "BitLGM"
    else:
        return "BitAryo"

